PREPARE = '#!/bin/bash\n#\n# /usr/lib/live/mount/medium/claugine/vyos-image-prepare - on customized VyOS ISO\n# Creates initial config and writes vyos-postconfig-bootup.script\n#\n# Runs in VM console session booted from the customized VyOS ISO:\n#   - login using vyos/vyos\n#   - run "install image" - answer "yes" on all questions\n#   - run "bash /usr/lib/live/mount/medium/claugine/vyos-image-prepare"\n#\n# When the VM is powered off: phase=finalize (vyos_image_to_platforms)\n#\n# Vladislav Kirilin, https://claugine.com, 2026-10-13\n\nset -u\n\nSCRIPT_NAME=$(readlink -f "$0")\nSOURCE_DIR=$(dirname ${SCRIPT_NAME})\nVYOS_DIR="/mnt/vyos"\nCONTEXT_DIR="/mnt/context"\n\nif ! part=$(sudo blkid -L persistence)\nthen\n  echo "!!! ERROR !!! Run \\"install image\\" first"\n  exit 1\nfi\necho "installed VyOS: ${part}"\n\nsudo mkdir -p "${VYOS_DIR}"\nsudo mount "${part}" "${VYOS_DIR}"\nCONFIG=$(sudo ls -d "${VYOS_DIR}"/boot/*/rw/opt/vyatta/etc/config)\n\nsudo mkdir -p "${CONTEXT_DIR}"\nsudo mount -o ro "$(sudo blkid -L CONTEXT)" "${CONTEXT_DIR}"\nsource <(sudo cat "${CONTEXT_DIR}/context.sh")\necho "context data: loaded"\n\npswd="$(base64 -d -w 0 <<< "${CRYPTED_PASSWORD_BASE64:-}" 2>/dev/null)"\nfooter="$(sudo grep \'^//\' "${CONFIG}/config.boot" 2>/dev/null)"\n\necho "setup config:"\nsudo tee /tmp/config.boot <<EOF\ninterfaces {\n    loopback lo {\n    }\n}\nservice {\n    ssh {\n        client-keepalive-interval 120\n        disable-host-validation\n        port 22\n    }\n}\nsystem {\n    config-management {\n        commit-revisions 100\n    }\n    host-name vyos-router\n    login {\n        user vyos {\n            authentication {\n                encrypted-password "${pswd}"\n            }\n        }\n    }\n    option {\n        ctrl-alt-delete ignore\n        reboot-on-panic\n        reboot-on-upgrade-failure 5\n    }\n    syslog {\n        local {\n            facility all {\n                level info\n            }\n            facility local7 {\n                level debug\n            }\n        }\n    }\n}\n\n${footer}\nEOF\nsudo install -m 660 -g vyattacfg /tmp/config.boot "${CONFIG}/config.boot"\n\necho "setup scripts"\nsudo install -d -m 775 -g vyattacfg "${CONFIG}/scripts"\nfor script in "${SOURCE_DIR}"/*\ndo\n  [[ "${script}" == "${SCRIPT_NAME}" ]] && continue\n  echo "  ${script}"\n  sudo install -m 775 -g vyattacfg "${script}" "${CONFIG}/scripts/"\ndone  # script\n\nsync\nsudo umount "${VYOS_DIR}"\necho "done - power off in 10 seconds; then on the admin host: vyos_image_to_platforms"\nsleep 10\npoweroff\n'

BOOTUP = '#!/bin/bash\n#\n# /config/scripts/vyos-postconfig-bootup.script\n#   - called by VyOS on boot, after the config is loaded\n#   - first run: no flag /opt/vyatta/etc/init.flag; the flag is written after the first run\n#\n#   Custom context variables:\n#     VYOS_CONFIG_REAPPLY=YES|NO (NO) - apply context variables on every boot, not only the first\n#     CONTEXT_SCRIPTS_ENFORCE=YES|NO (NO) - run custom context scripts on every boot, not only the first\n#     ONE_TIME_INIT_SCRIPT_BASE64 - custom onetime init script, executed once before CUSTOM CONTEXT SCRIPTS\n#\n#   - applied context variables:\n#       - ETH{0..9}_ - all ethernet interfaces and static routes deleted before\n#           _MAC - the interface ethN is configured only if present\n#           _MTU (1500)\n#           _IP\n#           _MASK (255.255.255.0)\n#           _GATEWAY\n#           _METRIC (100) - distance of the default route and of _ROUTES\n#           _ROUTES - "NET via GW, NET via GW"\n#      - SET_HOSTNAME (vyos-router)\n#      - USERNAME (vyos) - the login user; user vyos disabled if USERNAME is another user;\n#          a user of a former USERNAME stays\n#      - CRYPTED_PASSWORD_BASE64 - changed for USERNAME\n#      - TIMEZONE (Asia/Almaty)\n#      - SSH_PORT (22) - enabled on all interfaces\n#      - SSH_PUBLIC_KEY - with a key: password authentication disabled; without: allowed\n#\n#  Custom context scripts:\n#    - all *.sh on context cd-rom except context.sh\n#    - runs in alphabetical order\n#    - will run on first run\n#    - on next runs will run only if CONTEXT_SCRIPTS_ENFORCE=YES\n#    - run with group vyattacfg\n#\n# Vladislav Kirilin, https://claugine.com, 2026-10-21\n\nCONTEXT_DIR="/mnt"\nCONTEXT_DATA="${CONTEXT_DIR}/context.sh"\nFLAG="/opt/vyatta/etc/init.flag"\nonetime_init=""\nconf="/opt/vyatta/sbin/vyatta-cfg-cmd-wrapper"\n# the VyOS environment of the config commands (validators, templates)\nsource /etc/default/vyatta\n\n\n# ---- boot: the context CD, the context variables, the context scripts, the flag\necho "----------------------------------------"\necho "contextualization - started"\n\n# the context CD by its label: an ISO attached to the VM can be /dev/sr0; sr0 only if no label is found\nCONTEXT_DEV="$(blkid -L CONTEXT 2>/dev/null)"\nmount "${CONTEXT_DEV:-/dev/sr0}" ${CONTEXT_DIR} &>/dev/null\nsource ${CONTEXT_DATA}\n\nVYOS_CONFIG_REAPPLY="${VYOS_CONFIG_REAPPLY:-NO}"\nCONTEXT_SCRIPTS_ENFORCE="${CONTEXT_SCRIPTS_ENFORCE:-NO}"\n\n# first run: no flag - the image after vyos-image-prepare\nFIRST_RUN=no\n[[ -f "${FLAG}" ]] || FIRST_RUN=yes\n\n# context variables: on the first run, on the next runs only if VYOS_CONFIG_REAPPLY=YES\nif [[ "${FIRST_RUN}" == "yes" || "${VYOS_CONFIG_REAPPLY^^}" == "YES" ]]\nthen\n  echo "context variables - applied: first run=${FIRST_RUN}, VYOS_CONFIG_REAPPLY=${VYOS_CONFIG_REAPPLY}"\n\n  SET_HOSTNAME="${SET_HOSTNAME:-vyos-router}"\n  TIMEZONE="${TIMEZONE:-Asia/Almaty}"\n  USERNAME="${USERNAME:-vyos}"\n  CRYPTED_PASSWORD_BASE64="${CRYPTED_PASSWORD_BASE64:-}"\n  SSH_PORT="${SSH_PORT:-22}"\n  SSH_PUBLIC_KEY="${SSH_PUBLIC_KEY:-}"\n  DEFAULT_MTU=1500\n  DEFAULT_METRIC=100\n\n  vyos_config=( begin )\n  vyos_config+=( "set system host-name ${SET_HOSTNAME}" )\n  vyos_config+=( "set system time-zone ${TIMEZONE}" )\n  vyos_config+=( "set service ssh port ${SSH_PORT}" )\n  vyos_config+=( "set service ssh disable-password-authentication" )\n\n  if [[ "${USERNAME}" == "vyos" ]]\n  then\n    vyos_config+=( "delete system login user vyos disable" )\n  else\n    vyos_config+=( "set system login user vyos disable" )\n  fi\n\n  if [[ -n "${CRYPTED_PASSWORD_BASE64}" ]]\n  then\n    pswd="$(base64 -d -w 0 <<< "${CRYPTED_PASSWORD_BASE64}")"\n    vyos_config+=( "set system login user ${USERNAME} authentication encrypted-password \'${pswd}\'" )\n  fi\n\n  if [[ -n "${SSH_PUBLIC_KEY}" ]]\n  then\n    key_type="$(cut -f 1 -d " " <<< "${SSH_PUBLIC_KEY}")"\n    key_pub="$(cut -f 2 -d " " <<< "${SSH_PUBLIC_KEY}")"\n    vyos_config+=( \n      "set system login user ${USERNAME} authentication public-keys ${USERNAME} type ${key_type}"\n      "set system login user ${USERNAME} authentication public-keys ${USERNAME} key ${key_pub}"\n      "set service ssh disable-password-authentication"\n    )\n  else\n    vyos_config+=( "delete service ssh disable-password-authentication" )\n  fi\n  vyos_config+=( "delete service ssh listen-address" )\n\n  vyos_config+=( "delete interfaces ethernet" )\n  vyos_config+=( "delete protocols static" )\n\n  for n in {0..9}\n  do\n    MAC="ETH${n}_MAC"\n    [[ -z "${!MAC:-}" ]] && continue\n\n    mtu="ETH${n}_MTU"\n    ip="ETH${n}_IP"\n    mask="ETH${n}_MASK"\n    gw="ETH${n}_GATEWAY"\n    metric="ETH${n}_METRIC"\n    routes="ETH${n}_ROUTES"\n\n    mtu="${!mtu:-${DEFAULT_MTU}}"\n    ip="${!ip:-}"\n    mask="${!mask:-255.255.255.0}"\n    gw="${!gw:-}"\n    metric="${!metric:-${DEFAULT_METRIC}}"\n    routes="${!routes:-}"\n\n    vyos_config+=( "set interfaces ethernet eth${n} mtu ${mtu}" )\n    vyos_config+=( "set interfaces ethernet eth${n} ipv6 address no-default-link-local" )\n    vyos_config+=( "set interfaces ethernet eth${n} ipv6 disable-forwarding" )\n\n    [[ -z "${ip}" ]] && continue\n\n    prefix=0\n    for oct in ${mask//./ }\n    do\n      case ${oct} in\n        255) (( prefix += 8 )) ;;\n        254) (( prefix += 7 )) ;;\n        252) (( prefix += 6 )) ;;\n        248) (( prefix += 5 )) ;;\n        240) (( prefix += 4 )) ;;\n        224) (( prefix += 3 )) ;;\n        192) (( prefix += 2 )) ;;\n        128) (( prefix += 1 )) ;;\n          0) break ;;\n      esac\n    done  # oct\n    vyos_config+=( "set interfaces ethernet eth${n} address ${ip}/${prefix}" )\n\n    if [[ ${gw} =~ ([0-9]{1,3}\\.){3}[0-9]{1,3} ]]\n    then\n      vyos_config+=( "set protocols static route 0.0.0.0/0 next-hop ${gw} distance ${metric}" )\n    fi\n\n    IFS=\',\' read -ra routes <<< "${routes}"\n    for route in "${routes[@]}"\n    do\n      route_data=( ${route} )\n      [[ ${#route_data[@]} == 3 ]] && vyos_config+=( "set protocols static route ${route_data[0]} next-hop ${route_data[2]} distance ${metric}" )\n    done  # route\n  done  # n\n\n  # every step prints its result, a failed step stops the session\n  vyos_config+=(\n    "commit && echo \'commit: ok\' || { echo \'commit: failed\'; exit 1; }"\n    "save && echo \'save: ok\' || { echo \'save: failed\'; exit 1; }"\n    "end && echo \'end: ok\' || { echo \'end: failed\'; exit 1; }"\n  )\n\n  script=""\n  for line in "${vyos_config[@]}"\n  do\n    echo "  ${line}"\n    script+="${conf} ${line}"$\'\\n\'\n  done  # line\n  if ! sg vyattacfg -c "${script}"\n  then\n    echo "!!! ERROR !!! context variables - not applied, see above"\n    FIRST_RUN=failed   # the first run is repeated on the next boot - no flag\n  fi\nelse\n  echo "context variables - skipped: not the first run, VYOS_CONFIG_REAPPLY=${VYOS_CONFIG_REAPPLY}"\nfi\n\nif [[ "${FIRST_RUN}" == "yes" && -n "${ONE_TIME_INIT_SCRIPT_BASE64:-}" ]]\nthen\n  onetime_init="/tmp/one-time-init-script.sh"\n  echo "one-time init script detected - ${onetime_init}"\n  base64 -d -w 0 <<< "${ONE_TIME_INIT_SCRIPT_BASE64}" > "${onetime_init}"\nfi\n\nif [[ "${FIRST_RUN}" == "yes" || "${CONTEXT_SCRIPTS_ENFORCE^^}" == "YES" ]]\nthen\n  for script in ${onetime_init} ${CONTEXT_DIR}/*.sh\n  do\n    [[ "${script}" == "${CONTEXT_DATA}" || ! -f "${script}" ]] && continue\n    echo "context script - ${script}"\n    echo "- - - - - - - - - -"\n    sg vyattacfg -c "/bin/bash ${script}"\n  done  # script\nelse\n  echo "context scripts - skipped: not the first run, CONTEXT_SCRIPTS_ENFORCE=${CONTEXT_SCRIPTS_ENFORCE}"\nfi\n\numount ${CONTEXT_DIR} &>/dev/null\necho "contextualization - finished"\necho "----------------------------------------"\n\n\n# first run: the flag and a reboot - the routing engine (FRR) installs the static routes only after it\nif [[ "${FIRST_RUN}" == "yes" ]]\nthen\n  date \'+initialized on %A, %B %d, %Y at %H:%M:%S GMT%Z\' > ${FLAG}\n  echo "----------------------------------------"\n  ${conf} show configuration | /usr/bin/vyos-config-to-commands\n  echo "----------------------------------------"\n  echo "reboot in 10 seconds"\n  sleep 10\n  reboot\nelse\n  cat "${FLAG}" 2>/dev/null\nfi\n'


DESCRIPTIONS = {'egw': "Provider VM in front of a tenant's main public network. eth1 the internet exchange (zone IX): iBGP to the exchange's route reflectors, connected and static routes redistributed (the tenant's routed networks via its igw). eth2 the tenant's public subnets (zone CLIENT): to and from the internet with martians dropped; the router answers them ping only. Bandwidth limited to the tenant's Mbps on eth1. Management: eth0 in VRF MGMT, zone MGMT — ping and ssh only from the management hosts; ssh nowhere else. NIC addresses, MTU, host name (= VM name), time zone and the login user come from the OpenNebula context at the first boot (the image's first-boot script).", 'igw': "The tenant's own router, under the tenant's full responsibility: EXT the main public network (ssh only from the hosts the tenant allows, with the tenant's keys), INT private networks behind SNAT, PUB extra public networks; no management NIC, no logs to the provider. The site gateway (core service cloud-igw) is built from it with the management part (eth0 in VRF MGMT, zone MGMT, ssh there only — none on EXT) and its own differences.", 'cgw': "Provider VM in front of a tenant's corporate network. eth1 the corporate exchange (zone IX): iBGP to its route reflectors. The tenant's corporate subnets (zone CLIENT): only to and from the exchange; the router answers them ping only. Management: eth0 in VRF MGMT, zone MGMT — ping and ssh only from the management hosts; ssh nowhere else. NIC addresses, MTU, host name (= VM name), time zone and the login user come from the OpenNebula context at the first boot (the image's first-boot script).", 'l2-a': "L2 channel, tenant side: bridges the tenant network (eth2) into a VXLAN tunnel to the external side, carried in WireGuard over the s2s network (eth1); keys and the pre-shared key made at random per channel and kept nowhere else. Zones: S2S (eth1) — WireGuard with the other side only; TUN (the WireGuard interface) — VXLAN with the other side only; the bridged frames are not filtered. Management: eth0 in VRF MGMT, zone MGMT — ping and ssh only from the management hosts; ssh nowhere else. NIC addresses, MTU, host name (= VM name), time zone and the login user come from the OpenNebula context at the first boot (the image's first-boot script).", 'l2-b': "L2 channel, external side: bridges the external VLAN (eth2) into the same VXLAN-in-WireGuard tunnel over the s2s network (eth1); it runs on the site's management platform. Zones: S2S (eth1) — WireGuard with the other side only; TUN (the WireGuard interface) — VXLAN with the other side only; the bridged frames are not filtered. Management: eth0 in VRF MGMT, zone MGMT — ping and ssh only from the management hosts; ssh nowhere else. NIC addresses, MTU, host name (= VM name), time zone and the login user come from the OpenNebula context at the first boot (the image's first-boot script).", 'l2-br': "L2 channel in one VM on the edge cluster of the tenant's platform: bridges the external VLAN (eth1) and the tenant network (eth2); no addresses on them, nothing reaches the router there. Management: eth0 in VRF MGMT, zone MGMT — ping and ssh only from the management hosts; ssh nowhere else. NIC addresses, MTU, host name (= VM name), time zone and the login user come from the OpenNebula context at the first boot (the image's first-boot script).", 'rr-inet': "Route reflector of the internet exchange (eth1, zone IX: BGP and ping with the exchange network only): eBGP to the uplinks, iBGP to the tenants' egw (route reflector clients, the uplinks' routes exported to them) and to the other route reflectors. Management: eth0 in VRF MGMT, zone MGMT — ping and ssh only from the management hosts; ssh nowhere else. NIC addresses, MTU, host name (= VM name), time zone and the login user come from the OpenNebula context at the first boot (the image's first-boot script).", 'rr-corpnet': "Route reflector of the corporate exchange (eth1, zone IX: BGP and ping with the exchange network only): eBGP to the corporate uplinks, iBGP to the tenants' cgw (route reflector clients) and to the other route reflectors. Management: eth0 in VRF MGMT, zone MGMT — ping and ssh only from the management hosts; ssh nowhere else. NIC addresses, MTU, host name (= VM name), time zone and the login user come from the OpenNebula context at the first boot (the image's first-boot script).", 'rr-vxlan': "Route reflector of the VXLAN/EVPN underlay (eth1, zone IX: BGP and ping with the underlay and its BGP peers only): iBGP (ipv4 and l2vpn-evpn) with the KVM hosts' FRR (route reflector clients) and with the other route reflectors. Management: eth0 in VRF MGMT, zone MGMT — ping and ssh only from the management hosts; ssh nowhere else. NIC addresses, MTU, host name (= VM name), time zone and the login user come from the OpenNebula context at the first boot (the image's first-boot script)."}


